import { wp, table, text, boolean, ref, defineConfig } from "spacepress";
export const posts = wp.posts.extend({ subtitle: text().max(200).optional() }, { url: "/blog/:slug", sync: "content/posts/*.md" });
export const tasks = table({ title: text().min(1).max(120), done: boolean().default(false), postId: ref(posts).optional().onDelete("cascade") }, { access: { read: "anyone", create: "authenticated", update: "authenticated", delete: "editor" } });
export default defineConfig({ name: "eval-schema" });

import { table, text, integer, defineConfig } from "spacepress";
export const notes = table({ ownerId: integer(), body: text().min(1), internalNote: text().optional().access({ read: "admin" }) }, { access: { read: ({ user }) => (user ? { ownerId: user.id } : false), create: "authenticated", update: ({ user }) => (user ? { ownerId: user.id } : false), delete: "admin" } });
export default defineConfig({ name: "eval-access" });

import { table, text, integer, timestamp, job, jobs, db, defineConfig } from "spacepress";
export const subscriptions = table({ email: text().max(191).unique(), welcomedAt: timestamp().optional() }, { access: { read: "admin", create: "anyone", update: "admin", delete: "admin" } }).on({ async afterCreate(row) { await jobs.sendWelcome.enqueue({ id: row.id }, { key: `welcome-${row.id}` }); } });
export const sendWelcome = job({ input: { id: integer() }, retries: 3, async handler({ id }) { await db.update(subscriptions).set({ welcomedAt: new Date().toISOString() }).where({ id }); } });
export default defineConfig({ name: "eval-jobs" });

import { table, text, boolean, defineConfig } from "spacepress";
export const tasks = table({ title: text().min(1), done: boolean().default(false) }, { access: { read: "anyone", create: "authenticated", update: "authenticated", delete: "editor" } });
export default defineConfig({ name: "eval-headful" });

