import { store, product, productCategory, order, defineConfig } from "spacepress";
export const shop = store({ currency: "USD", country: "US", sellTo: ["US"], shipping: [{ name: "US", countries: ["US"], methods: [{ type: "flatRate", title: "Standard", cost: "10.00" }] }], payments: ["cod"] });
export const products = product({ sync: "content/products/*.md", url: "/products/:slug" });
export const categories = productCategory({ url: "/shop/:path" });
export const orders = order();
export default defineConfig({ name: "eval-woo" });

import { table, text, defineConfig } from "spacepress";
